<template><div><div class="page-title"><div><h1>调班与替班申请</h1><p>主管审批后，系统会原子性更新双方排班记录。</p></div></div><el-card><el-table :data="rows"><el-table-column prop="id" label="#" width="70"/><el-table-column label="申请人"><template #default="scope">{{scope.row.applicant?.name}}</template></el-table-column><el-table-column label="替班人"><template #default="scope">{{scope.row.substitute?.name}}</template></el-table-column><el-table-column prop="reason" label="调班原因"/><el-table-column prop="status" label="状态"/><el-table-column v-if="auth.role!=='staff'" label="操作"><template #default="scope"><el-button size="small" type="success" :disabled="scope.row.status!=='pending'" @click="review(scope.row,true)">同意</el-button><el-button size="small" :disabled="scope.row.status!=='pending'" @click="review(scope.row,false)">驳回</el-button></template></el-table-column></el-table></el-card></div></template>
<script setup lang="ts">
import {onMounted, ref} from 'vue'; import {ElMessage} from 'element-plus'; import api from '../api/http'; import {auth} from '../stores/auth'
const rows=ref<any[]>([]); async function load(){rows.value=await api.get('/shift-requests')}; async function review(row:any,approved:boolean){try{await api.put(`/shift-requests/${row.id}/review`,{approved});ElMessage.success('审批已完成');await load()}catch(error:any){ElMessage.error(error.message)}}; onMounted(load)
</script>